


export type DeliveryPickupAvailabilityDiagnostic = { /** Stable reason a configured pickup location was left out of the results or cannot supply the order. - `PICKUP_LOCATION_INACTIVE`: The Location is inactive, so it was left out. - `PICKUP_LOCATION_GEOGRAPHY_UNAVAILABLE`: The Location has no usable published geography, so it was left out. - `PICKUP_LOCATION_INVENTORY_UNAVAILABLE`: The Location does not allocate inventory, so it cannot supply the order's tracked items. It is listed with an unavailable outcome. Items without tracked inventory need no allocation. - `PICKUP_LOCATION_DEPENDENCY_FAILURE`: Flint could not resolve the configured Location. */ "code": "PICKUP_LOCATION_INACTIVE" | "PICKUP_LOCATION_GEOGRAPHY_UNAVAILABLE" | "PICKUP_LOCATION_INVENTORY_UNAVAILABLE" | "PICKUP_LOCATION_DEPENDENCY_FAILURE" | (string & {}); "diagnostic_id": string; "location_id": string; /** RFC3339 timestamp. Format: date-time. */ "occurred_at": string; "outcome": "unavailable" | "cannot_calculate" | (string & {}); "recommended_action": "review_configuration" | "retry" | (string & {}); "retryable": boolean; "scope": "location" | (string & {}); "summary": string; };
